<?php

namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\Business;use App\Models\OrderItem;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;
class BarQueueController{
 public function index(Request $request):JsonResponse{$location=$request->string('location_id')->toString();$items=OrderItem::query()->forBusiness(app(Business::class))->whereIn('preparation_status',['sent','preparing','ready'])->when($location!=='',fn($q)=>$q->whereHas('order',fn($o)=>$o->where('location_id',$location)))->when($request->string('station')->isNotEmpty(),fn($q)=>$q->where('preparation_station',$request->string('station')->toString()))->with('order')->orderByRaw("FIELD(preparation_status, 'preparing', 'sent', 'ready')")->orderBy('sent_at')->get();return response()->json(['data'=>$items]);}
 public function transition(Request $request,string $item):JsonResponse{$v=$request->validate(['status'=>['required',Rule::in(['preparing','ready','served'])],'location_id'=>['required','string']]);$r=DB::transaction(function()use($item,$v){$r=OrderItem::query()->forBusiness(app(Business::class))->whereKey($item)->whereHas('order',fn($q)=>$q->where('location_id',$v['location_id']))->lockForUpdate()->firstOrFail();$a=['sent'=>'preparing','preparing'=>'ready','ready'=>'served'];if(($a[$r->preparation_status]??null)!==$v['status'])throw ValidationException::withMessages(['status'=>'Invalid preparation status transition.']);$u=['preparation_status'=>$v['status']];if($v['status']==='ready')$u['prepared_at']=now();$r->forceFill($u)->save();return $r->fresh('order');});return response()->json(['data'=>$r]);}
}
